package com.example.text;

import everythingrust.EverythingRustError;

/**
 * {@code hash} over many {@code text} values kept in Rust, generated by everything-rust: built once,
 * then each {@link #run} maps them all in one call, on all cores. Safe for concurrent use;
 * close it when done (a Cleaner frees it otherwise).
 */
public final class HashBatch implements AutoCloseable {
    static {
        try {
            Class.forName("everythingrust.TextRsNative");
        } catch (ClassNotFoundException e) {
            throw new ExceptionInInitializerError(e);
        }
    }

    private static final java.lang.ref.Cleaner CLEANER = java.lang.ref.Cleaner.create();

    /** The Rust handle; freed once, by {@link #close} or the Cleaner. */
    private static final class State implements Runnable {
        private long handle;

        State(long handle) {
            this.handle = handle;
        }

        @Override
        public synchronized void run() {
            if (handle != 0) {
                nFree(handle);
                handle = 0;
            }
        }

        synchronized long get() {
            if (handle == 0) {
                throw new IllegalStateException("HashBatch is closed");
            }
            return handle;
        }
    }

    private final State state;
    private final java.lang.ref.Cleaner.Cleanable cleanable;
    private final int count;

    /** Copies the items into Rust. */
    public HashBatch(String[] texts) {
        state = new State(nNew(texts));
        count = texts.length;
        cleanable = CLEANER.register(this, state);
    }

    /** Copies the items into Rust. */
    public HashBatch(java.util.List<String> texts) {
        this(texts.toArray(new String[0]));
    }

    private long handle() {
        return state.get();
    }

    /** {@code hash}'s result for every item, in order. */
    public int[] run() {
        String[] slot = EverythingRustError.slot();
        int[] out = nRun(handle(), slot);
        EverythingRustError.check(slot);
        java.lang.ref.Reference.reachabilityFence(this);
        return out;
    }

    /** Indexes of the items whose result is at least {@code min}, highest result first. */
    public int[] rank(double min) {
        String[] slot = EverythingRustError.slot();
        int[] out = nRank(handle(), min, slot);
        EverythingRustError.check(slot);
        java.lang.ref.Reference.reachabilityFence(this);
        return out;
    }

    private static native int[] nRank(long handle, double min, String[] slot);

    /** Frees the items on the Rust side. */
    @Override
    public void close() {
        cleanable.clean();
    }

    private static native long nNew(String[] items);

    private static native void nFree(long handle);

    private static native int[] nRun(long handle, String[] slot);
}
